"""
Кириллический TTF-шрифт (DejaVu Sans, урезанный subset: базовая латиница +
кириллица + типографские знаки) встроен как base64, а не отдельным .ttf-
файлом рядом с index.py — деплой облачной функции переносит .py-модули той
же папки, но НЕ переносит произвольные бинарные файлы (проверено эмпирически
через action=_debug_ls: .ttf исчезал из /function/code, .py оставался).
Используется в export_completeness_pdf для регистрации Unicode-шрифта в
reportlab, иначе кириллица отображается квадратами (раздел 7 ТЗ итерации 4).
"""
import base64

DEJAVU_SANS_REGULAR_B64 = ""

DEJAVU_SANS_BOLD_B64 = ""


def regular_bytes() -> bytes:
    return base64.b64decode(DEJAVU_SANS_REGULAR_B64)


def bold_bytes() -> bytes:
    return base64.b64decode(DEJAVU_SANS_BOLD_B64)
